class Solution:
    def differenceOfSum(self, nums: list[int]) -> int:
        elem_sum = sum(nums)
        digit_sum = sum(int(d) for x in nums for d in str(x))
        return elem_sum - digit_sum

class Solution {
public:
    int differenceOfSum(std::vector<int>& nums) {
        int elem_sum = 0, digit_sum = 0;
        for (int x : nums) {
            elem_sum += x;
            int temp = x;
            while (temp > 0) {
                digit_sum += temp % 10;
                temp /= 10;
            }
        }
        return elem_sum - digit_sum;
    }
};

