var differenceOfSum = function(nums) {
    let elemSum = 0, digitSum = 0;
    for (const x of nums) {
        elemSum += x;
        let temp = x;
        while (temp > 0) {
            digitSum += temp % 10;
            temp = Math.floor(temp / 10);
        }
    }
    return elemSum - digitSum;
};
